import { EmptyState, StatusBadge, type StatusTone } from "@/components/app/ui"
import type { BillingInvoiceView } from "@/server/billing"

/**
 * The invoice list.
 *
 * The PDF is not served from here: WHMCS is the accounting book of record, so the customer
 * follows a single-use SSO link into its client area and downloads the real document. No
 * copy of an invoice is ever generated by this app.
 */

const TONE: Readonly<Record<BillingInvoiceView["status"], StatusTone>> = {
  unpaid: "warn",
  paid: "ok",
  cancelled: "neutral",
  refunded: "neutral",
}

function dateLabel(value: Date | null): string {
  if (!value) return "—"
  return value.toLocaleDateString("es-ES", { day: "2-digit", month: "short", year: "numeric" })
}

export function InvoiceTable({
  invoices,
  clientAreaUrl,
}: {
  invoices: readonly BillingInvoiceView[]
  clientAreaUrl: string | null
}) {
  if (invoices.length === 0) {
    return <EmptyState>Todavía no tienes facturas. Aparecerán aquí tras tu primer pago.</EmptyState>
  }

  return (
    <div>
      <div className="overflow-x-auto -mx-6 px-6">
        <table className="w-full min-w-[32rem] text-sm">
          <thead>
            <tr className="border-b border-border-base">
              <th scope="col" className="label-mono text-text-muted text-left py-2">
                Número
              </th>
              <th scope="col" className="label-mono text-text-muted text-left py-2">
                Fecha
              </th>
              <th scope="col" className="label-mono text-text-muted text-right py-2">
                Importe
              </th>
              <th scope="col" className="label-mono text-text-muted text-right py-2">
                Estado
              </th>
              <th scope="col" className="label-mono text-text-muted text-right py-2">
                PDF
              </th>
            </tr>
          </thead>
          <tbody>
            {invoices.map((invoice) => (
              <tr key={invoice.id} className="border-b border-border-base last:border-b-0">
                <td className="py-3 font-mono text-text-base">{invoice.reference}</td>
                <td className="py-3 text-text-muted">{dateLabel(invoice.issuedAt)}</td>
                <td className="py-3 text-right text-text-base">{invoice.totalLabel}</td>
                <td className="py-3 text-right">
                  <StatusBadge tone={TONE[invoice.status]}>{invoice.statusLabel}</StatusBadge>
                </td>
                <td className="py-3 text-right">
                  {clientAreaUrl ? (
                    <a
                      href={clientAreaUrl}
                      target="_blank"
                      rel="noreferrer"
                      className="label-mono text-text-base underline decoration-border-base hover:decoration-accent-ink"
                    >
                      Descargar
                    </a>
                  ) : (
                    <span className="label-mono text-text-muted">no disponible</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {clientAreaUrl === null ? (
        <p className="mt-4 text-[13px] text-text-muted">
          No hemos podido preparar el acceso a los PDF ahora mismo. Vuelve a cargar la página en
          unos minutos o escríbenos y te los enviamos.
        </p>
      ) : (
        <p className="mt-4 text-[13px] text-text-muted">
          Los PDF se descargan desde nuestro sistema de facturación. El enlace caduca en unos
          minutos por seguridad.
        </p>
      )}
    </div>
  )
}
